  function globalSearch(q){const out=$('#searchResults'),n=normal(q);if(!n){out.hidden=true;return}const ps=fuzzyPatients(q).slice(0,4).map(({x:p})=>`<button class="search-result" data-open="${p.id}"><span class="avatar">${initials(p.name)}</span><span><b>${esc(p.name)}</b><small>${esc(p.notes||p.dailyNote||'Patient')}</small></span></button>`);const ms=state.materials.filter(m=>normal(m.name).includes(n)||lev(normal(m.name),n)<=3).slice(0,3).map(m=>`<button class="search-result" data-view="materials"><span>📦</span><span><b>${esc(m.name)}</b><small>Material</small></span></button>`);const extras=[['Kalender','calendar'],['Statistik','statistics'],['Berichte','reports'],['PflegePilot','home']].filter(x=>normal(x[0]).includes(n)).map(x=>`<button class="search-result" data-view="${x[1]}"><span>⌕</span><span><b>${x[0]}</b><small>Bereich öffnen</small></span></button>`);out.hidden=!(ps.length||ms.length||extras.length);out.innerHTML=[...ps,...ms,...extras].join('')||'<div class="search-result">Keine passenden Daten gefunden.</div>'}
  function ask(q){const c=$('#pilotChat'),n=normal(q),p=patientFromText(q);c.insertAdjacentHTML('beforeend',`<div class="chat-message user">${esc(q)}</div>`);let a='Gern. Wobei darf ich helfen?';const go=(id,label)=>{show(id);a=`Gern, ich öffne ${label}.`};if(/offne.*statistik/.test(n))go('statistics','die Statistik');else if(/offne.*kalender/.test(n))go('calendar','den Kalender');else if(/offne.*einstellung/.test(n))go('settings','die Einstellungen');else if(/materialliste|offne.*material/.test(n))go('todayMaterials','die Materialliste');else if(/heutige.*tour|erstell.*tour/.test(n))go('dayplan','Ihre Tour');else if(/pdf/.test(n)){printReport();a='Ich habe die professionell formatierte Druckansicht geöffnet. Sie können dort als PDF sichern.'}else if(/langsten/.test(n)){const x=state.patients.map(p=>({p,t:(p.visits||[]).filter(v=>v.start>Date.now()-604800000).reduce((s,v)=>s+(v.duration||0),0)})).sort((a,b)=>b.t-a.t).slice(0,3);a=`Diese Woche am längsten besucht: ${x.filter(x=>x.t).map(x=>`${x.p.name} (${fmt(x.t)})`).join(', ')||'noch keine Daten'}.`}else if(/morgen.*wahrscheinlich/.test(n)){const d=new Date();d.setDate(d.getDate()+1);const ps=(state.weekPlans[key(d)]||[]).map(id=>state.patients.find(p=>p.id===id)).filter(Boolean);a=`Für morgen wahrscheinlich: ${[...new Set(ps.flatMap(p=>p.materials||[]))].join(', ')||'noch keine Materialvorschläge'}.`}else if(/offne|suche|zeige/.test(n)&&p){openPatient(p);a=`Gern, ich öffne ${p.name}.`}else if(/kilometer/.test(n))a=`Heute sind ${Number(state.kilometers||0).toFixed(1)} Kilometer erfasst.`;else if(/arbeitsstunden|arbeite/.test(n))a=`Ihre Arbeitszeit heute beträgt ${fmt(secs()-pauseSeconds())}.`;c.insertAdjacentHTML('beforeend',`<div class="chat-message">${esc(a)}</div>`);c.scrollTop=c.scrollHeight}
