  function mapPosition(p,i){const h=[...p.id].reduce((s,c)=>s+c.charCodeAt(0),0);return {x:31+(h%38),y:13+((h*7+i*11)%66)}}
  function routePoints(){return active().filter(p=>p.address?.trim()).sort((a,b)=>a.order-b.order).map((p,i)=>({...p,...mapPosition(p,i)}))}
  function routeData(){const pts=routePoints();if(pts.length<2)return {pts,km:0,min:0};let raw=0;for(let i=1;i<pts.length;i++)raw+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);return {pts,km:Number((raw*.95).toFixed(1)),min:Math.max(0,Math.round(raw*1.15))}}
